// Set WEBHOOK_SECRET as an environment variable on the n8n server.
// Self-hosted n8n Code node must allow built-in crypto (NODE_FUNCTION_ALLOW_BUILTIN=crypto).
const crypto = require('crypto');
const input = $input.first().json;
const headers = input.headers || {};
const signature = String(headers['x-webhook-signature'] || headers['X-Webhook-Signature'] || '');
const secret = $env.WEBHOOK_SECRET;
if (!secret) return [{json:{ok:false,statusCode:500,message:'WEBHOOK_SECRET not configured'}}];
// Webhook rawBody option supplies the unparsed request body (typically input.body).
const raw = input.body;
if (typeof raw !== 'string') return [{json:{ok:false,statusCode:500,message:'Raw body not available; check Webhook Raw Body setting'}}];
const expected = 'sha256=' + crypto.createHmac('sha256',secret).update(raw,'utf8').digest('hex');
const a=Buffer.from(signature,'utf8'); const b=Buffer.from(expected,'utf8');
const valid=a.length===b.length && crypto.timingSafeEqual(a,b);
if (!valid) return [{json:{ok:false,statusCode:401,message:'Invalid or missing HMAC signature'}}];
let payload; try {payload=JSON.parse(raw)} catch(e) {return [{json:{ok:false,statusCode:400,message:'Invalid JSON payload'}}]};
if (!payload.event || !payload.customer_id) return [{json:{ok:false,statusCode:400,message:'event and customer_id are required'}}];
return [{json:{ok:true,statusCode:200,message:'Webhook received and verified',event:payload.event,customer_id:payload.customer_id,query:input.query||{},headerNames:Object.keys(headers)}}];
